package com.mst.controllers.sale;import com.mst.services.SaleGdnDirectService;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/sale/gdn-direct/api") public class SaleGdnDirectController{private final SaleGdnDirectService s;public SaleGdnDirectController(SaleGdnDirectService x){s=x;}@GetMapping("/initial")@ResponseBody public Map<String,Object>initial(){return s.initial();}@GetMapping("/uoms")@ResponseBody public List<Map<String,Object>>uoms(@RequestParam int itemId){return s.uoms(itemId);}@GetMapping("/history")@ResponseBody public List<Map<String,Object>>history(){return s.history();}@GetMapping("/{id:[0-9]+}")@ResponseBody public Map<String,Object>record(@PathVariable int id){return s.record(id);}@PostMapping@ResponseBody public Map<String,Object>save(@RequestBody Map<String,Object>r){r.put("id",0);return s.save(r);}@PutMapping("/{id:[0-9]+}")@ResponseBody public Map<String,Object>update(@PathVariable int id,@RequestBody Map<String,Object>r){r.put("id",id);return s.save(r);}@DeleteMapping("/{id:[0-9]+}")public ResponseEntity<Void>delete(@PathVariable int id){s.delete(id);return ResponseEntity.noContent().build();}}
